/* Human actions only. Importing source data does not earn activity credit. */
function renderLeaderboard(){let board=leaderboard(),cats=[['branches','จัดการสาขา','Branches'],['verification','ตรวจยืนยัน','Verification'],['locations','งานทำเล','Location work'],['criteria','ปรับเกณฑ์','Criteria']];return `<section class="section leaderboard"><div class="block-title"><div><p class="eyebrow">${tr('การมีส่วนร่วมของทีม','Team contribution')}</p><h2>${tr('ใครช่วยให้งานคืบหน้า','Who is moving the work forward?')}</h2></div><span class="tag">${num(board.total)} ${tr('การบันทึก','saved actions')}</span></div><div class="leader-filters"><div class="field"><label for="leader-period">${tr('ช่วงเวลา','Period')}</label><select id="leader-period">${[['7','7 วัน','7 days'],['30','30 วัน','30 days'],['all','ทั้งหมด','All time']].map(([v,th,en])=>`<option value="${v}" ${Y.leaderPeriod===v?'selected':''}>${tr(th,en)}</option>`).join('')}</select></div><div class="field"><label for="leader-category">${tr('ประเภทงาน','Action category')}</label><select id="leader-category">${[['all','ทุกประเภท','All categories'],...cats].map(([v,th,en])=>`<option value="${v}" ${Y.leaderCategory===v?'selected':''}>${tr(th,en)}</option>`).join('')}</select></div></div>${!board.total?`<p class="leader-empty">${tr('ยังไม่มีงานในช่วงนี้ เพิ่มทำเลหรืออัปเดตสาขาเพื่อเริ่มบันทึกผลงานทีม','No saved actions in this period. Shortlist a location or update a branch to start the team activity record.')}</p>`:''}<div class="leader-grid">${board.rows.map((r,i)=>`<article class="leader-row"><span class="leader-rank">${r.total?1+board.rows.filter(x=>x.total>r.total).length:'—'}</span><div class="leader-person"><strong>${escapeHTML(person(r.id))}</strong><small>${PEOPLE.find(p=>p.id===r.id).role} · ${num(r.entities)} ${tr('รายการที่มีส่วนร่วม','records contributed to')}</small></div><strong class="leader-total">${num(r.total)}</strong><dl class="leader-breakdown">${cats.map(([k,th,en])=>`<div><dt>${tr(th,en)}</dt><dd>${num(r.counts[k])}</dd></div>`).join('')}</dl></article>`).join('')}</div><p class="footline">${tr('นับเฉพาะงานที่บันทึกและเปลี่ยนข้อมูล ไม่รวมการเปิดดู ทดลองค่า หรือนำเข้า ใช้ดูการมีส่วนร่วม ไม่ใช่คุณภาพงาน','Counts committed changes only, excluding views, previews and imports. Activity volume shows participation, not work quality.')}</p></section>`}
